import{_ as o,C as n,o as a,c as i,a2 as t,E as r}from"./chunks/framework.9yf7n3zg.js";const h="/guide/media/comments-list.webp",d="/guide/media/comments-word-lists.webp",f=JSON.parse('{"title":"Comments and word lists","description":"","frontmatter":{},"headers":[],"relativePath":"guide/comments.md","filePath":"guide/comments.md","lastUpdated":1792685126000}'),l={name:"guide/comments.md"};function c(m,e,g,p,u,w){const s=n("Clip");return a(),i("div",null,[e[0]||(e[0]=t(`<h1 id="comments-and-word-lists" tabindex="-1">Comments and word lists <a class="header-anchor" href="#comments-and-word-lists" aria-label="Permalink to &quot;Comments and word lists&quot;">​</a></h1><p>This page covers two kinds of notes you keep beside your prose without writing them into it. <strong>Comments</strong> are remarks on a passage: your own, typed in your notes, and the ones you make on the <a href="/guide/guide/manuscript">manuscript</a> page, which Leathercase keeps in a file of its own. <strong>Word lists</strong> are the words you want to watch, which the words lens marks on the page. Both live in plain markdown files you can open and edit without Leathercase.</p><h2 id="two-kinds-of-comment" tabindex="-1">Two kinds of comment <a class="header-anchor" href="#two-kinds-of-comment" aria-label="Permalink to &quot;Two kinds of comment&quot;">​</a></h2><p>Every comment of a story sits in one list, but they come from two places:</p><table tabindex="0"><thead><tr><th></th><th>Your comments</th><th>Leathercase&#39;s comments</th></tr></thead><tbody><tr><td>Written</td><td>By you, in your notes, in your own app</td><td>On the manuscript page, in Leathercase</td></tr><tr><td>Kept in</td><td>The chapter itself, as <code>%% … %%</code> or <code>==…==</code></td><td><code>Comments.md</code> in the story&#39;s suite folder</td></tr><tr><td>Shown as</td><td><strong>in your note</strong></td><td><strong>suite</strong></td></tr><tr><td>Resolved or removed from Leathercase</td><td>No: change them in your note</td><td>Yes</td></tr></tbody></table><p>Leathercase reads your notes and never writes into them, which is why a comment made in Leathercase goes to a file beside the story and not into the chapter.</p><h3 id="your-own-comments-in-your-notes" tabindex="-1">Your own comments in your notes <a class="header-anchor" href="#your-own-comments-in-your-notes" aria-label="Permalink to &quot;Your own comments in your notes&quot;">​</a></h3><p>Leathercase reads two marks in your text:</p><ul><li><code>%% a comment %%</code>: a hidden comment, the kind Obsidian hides in reading view. It may span lines.</li><li><code>==a highlight==</code>: highlighted text. It shows highlighted on the page, and is listed as a <strong>mark</strong>.</li></ul><p>A comment that opens with an upper-case word and a colon has that word as its kind, the way code editors colour TODO and FIXME:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%% TODO: the eight-second rhythm needs to be felt before it is explained %%</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%% CHECK: was it a coat or a cape in chapter three? %%</span></span></code></pre></div><p>The kind colours the comment: <strong>todo</strong> and <strong>fix</strong> in the accent colour (something to do), <strong>check</strong> in the warning colour (something to verify), <strong>cut</strong> struck through, and any other kind, or none, muted. A lower-case &quot;check the gate&quot; is prose, not a kind. A comment that ends with <code>✓</code> is resolved.</p><p>Chapter one of The Lamp at Ferrol carries one: <code>%% TODO: the eight-second rhythm needs to be felt before it is explained %%</code>.</p><p>Comments inside front matter or code blocks are not read. A comment of the form <code>%% not cliche %%</code> is an instruction to the style lens, and <code>%% Tomás %%</code> before a line of speech pins its speaker (see <a href="/guide/guide/lenses">Lenses and style checks</a>).</p><h2 id="making-a-comment-on-the-page" tabindex="-1">Making a comment on the page <a class="header-anchor" href="#making-a-comment-on-the-page" aria-label="Permalink to &quot;Making a comment on the page&quot;">​</a></h2><ol><li>On the manuscript page, click a sentence (or drag over a passage, or move to a paragraph with the arrow keys).</li><li>In the side column&#39;s <strong>Passage</strong> section, click <strong>Comment on this passage</strong>.</li><li>The composer opens. Pick a <strong>Kind</strong> if you want one: <strong>no kind</strong>, <strong>todo</strong>, <strong>fix</strong>, <strong>check</strong>, <strong>idea</strong>, <strong>cut</strong> or <strong>ref</strong>.</li><li>Type in <strong>Comment on this paragraph…</strong>. <code>Enter</code> adds it; <code>Shift+Enter</code> starts a new line. Or click <strong>Add</strong>.</li></ol><p>The line under the field says what will happen: &quot;enter adds it · shift+enter for a new line · written to Comments.md in your suite folder, anchored to &quot;…&quot;&quot;, with the start of the sentence it hangs on. With nothing selected the field is greyed and says <strong>Pick a paragraph on the page…</strong>.</p><p>The comment is written to <code>Comments.md</code>, anchored to the sentence you selected, under the chapter and scene it is in. Your chapter is not touched. The status line at the foot of the page says <strong>Commented on ¶ 3 of The Night the Lamp Went Out</strong>, with <strong>Undo</strong>.</p>`,18)),r(s,{name:"comments-make",caption:"Selecting a sentence in The cottage, choosing the kind check, typing Slower here. and pressing Enter; the comment appears under the passage as Leathercase's"}),e[1]||(e[1]=t('<h2 id="the-comments-list" tabindex="-1">The comments list <a class="header-anchor" href="#the-comments-list" aria-label="Permalink to &quot;The comments list&quot;">​</a></h2><p><strong>All comments</strong>, the last section of the side column, lists every comment of the book in reading order. It is folded at first; its hint shows the count, or <code>2 open of 5</code> when some are resolved.</p><ul><li>Chapter names head each group, with the chapter&#39;s count and how many are open (<strong>1 open</strong>, or <strong>all resolved</strong>).</li><li>Each comment shows its kind in lower case (<strong>check</strong>, <strong>todo</strong>, <strong>note</strong> when it has none, <strong>mark</strong> for a highlight), who made it (<strong>suite</strong> or <strong>in your note</strong>), its text, and the line of prose it hangs on in italics.</li><li><strong>All</strong> and <strong>Open</strong> at the top switch between every comment and the open ones only.</li><li>Click a comment to go to its paragraph: the page scrolls there and selects it. The comment of the paragraph you are on is marked.</li></ul><p>Leathercase&#39;s own comments carry two small buttons, shown when you point at the comment:</p><table tabindex="0"><thead><tr><th>Button</th><th>Does</th></tr></thead><tbody><tr><td><code>✓</code></td><td><strong>Resolve</strong> the comment: it stays, greyed, with a <code>✓</code> added in <code>Comments.md</code>. On a resolved comment the same button is <strong>Reopen</strong>.</td></tr><tr><td><code>×</code></td><td><strong>Remove</strong> the comment from <code>Comments.md</code>.</td></tr></tbody></table><p>Both go on the page&#39;s undo stack. Your own comments have no buttons: change them in your note.</p><p>The comments on the paragraph you have selected are also listed in the <strong>Passage</strong> section, under the actions.</p><p>With no comment at all the list says: &quot;No comment yet. Pick a paragraph and write one below it; it goes to Comments.md in your suite folder. Your own %% comments %% and ==highlights== in the notes are listed here too.&quot;</p><p><img src="'+h+`" alt="The All comments section with chapter groups The Night the Lamp Went Out and The Ledger, a todo in your note and a check by Leathercase with its resolve and remove buttons" width="375" height="632" loading="lazy"></p><h2 id="how-a-comment-finds-its-place-again" tabindex="-1">How a comment finds its place again <a class="header-anchor" href="#how-a-comment-finds-its-place-again" aria-label="Permalink to &quot;How a comment finds its place again&quot;">​</a></h2><p>A comment of Leathercase&#39;s does not store a line number, which would break the first time you edited the chapter. It stores the chapter&#39;s name, the scene heading and the sentence you selected, and finds them again each time the story is read:</p><ol><li>The chapter, by its file name (with or without folders, in any case).</li><li>The scene, by its heading, inside the chapter.</li><li>The paragraph, by the quoted sentence, inside the scene. Punctuation, case and the kind of quote marks do not matter: a sentence quoted with straight, curly, single or double marks is the same sentence, so a quote never reads as <strong>sentence moved</strong> for its marks alone.</li></ol><p>A sentence you moved to another scene of the same chapter is still found there. If you rewrite the sentence, the comment still shows, on the scene&#39;s first paragraph, marked <strong>sentence moved</strong>. A comment made on a scene as a whole sits on its first paragraph.</p><h2 id="comments-md" tabindex="-1">Comments.md <a class="header-anchor" href="#comments-md" aria-label="Permalink to &quot;Comments.md&quot;">​</a></h2><p><code>Comments.md</code> is author data: a markdown file of Leathercase&#39;s, in the story&#39;s suite folder (<code>The Lamp at Ferrol/suite/Comments.md</code> for the sample, or the folder you chose under <strong>Leathercase&#39;s files go in</strong> in the story&#39;s settings). It is made with your first comment, and opens with a short paragraph saying what it is. Then one heading per scene, one line per comment:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## [[01 The Night the Lamp Went Out#The cottage]]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> check: &quot;The lamp went out at ten past two, and Nora knew it before she was awake.&quot; — Slower here.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> todo: The lamp pays off in part two. ✓</span></span></code></pre></div><ul><li>The heading links the chapter and scene, so it opens as a link in Obsidian.</li><li>The kind comes first, in lower case, then a colon.</li><li>The quoted sentence is the anchor; the text after the dash is the comment.</li><li>A trailing <code>✓</code> resolves it.</li></ul><p>You can edit the file by hand: add a line, change a kind, tick one off. Leathercase reads it again with the story. Undo from the page only writes the file back if it still holds what Leathercase wrote, so a change you made by hand is never overwritten.</p><h2 id="word-lists" tabindex="-1">Word lists <a class="header-anchor" href="#word-lists" aria-label="Permalink to &quot;Word lists&quot;">​</a></h2><p>A word list is a set of words or phrases you want to see on the page: words to cut, words never to use, your stage directions, your filter verbs. The words lens marks them, each list in its colour (see <a href="/guide/guide/lenses#words">Lenses and style checks</a>).</p><h3 id="editing-the-lists-on-the-settings-page" tabindex="-1">Editing the lists on the settings page <a class="header-anchor" href="#editing-the-lists-on-the-settings-page" aria-label="Permalink to &quot;Editing the lists on the settings page&quot;">​</a></h3><p>Open the story&#39;s settings (the story&#39;s <code>⋯</code> menu, <strong>Story settings</strong>) and pick <strong>Words</strong> on the left. The section heads with the file it writes, <code>WordLists.md</code>, and the line &quot;The words to watch. Each change is written at once to Leathercase&#39;s file beside the story.&quot;</p><p>Under <strong>The story&#39;s word lists</strong>:</p><ul><li>Each list is a row, its name in its colour, its words as chips. Click the <code>×</code> on a chip to take that word out (<strong>Take felt out of Filtering</strong>).</li><li>To add, type the list&#39;s name in <strong>List</strong> (it suggests the lists you have; the placeholder is <strong>Never use</strong>), the word or phrase in <strong>Word or phrase</strong> (placeholder <strong>suddenly</strong>), and press <code>Enter</code> or click <strong>Add</strong>. A new list name makes a new list.</li></ul><p>The note under the lists, &quot;How each character speaks is kept on their own sheet, in the characters view.&quot;, points to the accents, which are not word lists.</p><p><img src="`+d+`" alt="The Words section of the story&#39;s settings, with the lists Filtering and Never use as rows of chips and the fields to add a word" width="1130" height="510" loading="lazy"></p><h3 id="adding-from-the-page" tabindex="-1">Adding from the page <a class="header-anchor" href="#adding-from-the-page" aria-label="Permalink to &quot;Adding from the page&quot;">​</a></h3><p>With the words lens on the manuscript page, drag across a word or short phrase and use <strong>Put “felt” in a word list</strong>; select a marked paragraph and use <strong>Take “felt” out of the word lists</strong>. See <a href="/guide/guide/lenses#words">Lenses and style checks</a>.</p><h3 id="wordlists-md" tabindex="-1">WordLists.md <a class="header-anchor" href="#wordlists-md" aria-label="Permalink to &quot;WordLists.md&quot;">​</a></h3><p><code>WordLists.md</code> sits in the story&#39;s suite folder, beside <code>Comments.md</code>. One heading per list, the words under it, separated by commas or one to a line:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Filtering</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">felt, saw, heard, noticed</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Stage direction</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">colour: #7a4fd6</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">then, before, and then</span></span></code></pre></div><ul><li>A <code>colour: #hex</code> line under a heading fixes the list&#39;s colour. Without one, colours follow the order of the headings from Leathercase&#39;s palette.</li><li>Bullets are allowed. Words are matched without regard to case or curly apostrophes, and a phrase is matched as a whole.</li><li>Front matter, comments and code blocks are your own text: never read as words, and never where Leathercase writes.</li></ul><p>Leathercase writes the file only when you add or take out a word, and keeps the rest of it, your own lines too, as you wrote them. The story&#39;s settings page lists it under <strong>Leathercase&#39;s files</strong> with the note &quot;yours to write: a heading per category, the words under it&quot; until it exists.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/manuscript">Manuscript</a></li><li><a href="/guide/guide/lenses">Lenses and style checks</a></li><li><a href="/guide/guide/story-settings">Story settings</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li></ul>`,35))])}const y=o(l,[["render",c]]);export{f as __pageData,y as default};
